CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, role TEXT NOT NULL DEFAULT 'operator', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agents (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'idle', model TEXT NOT NULL, tools TEXT NOT NULL DEFAULT '[]', system_prompt TEXT DEFAULT '', temperature REAL DEFAULT .2, max_tokens INTEGER DEFAULT 4096, memory_config TEXT DEFAULT '{"enabled":true}', enabled INTEGER NOT NULL DEFAULT 1, success_rate REAL DEFAULT 0, avg_latency INTEGER DEFAULT 0, total_executions INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_agents_status ON agents(status,enabled);
CREATE TABLE IF NOT EXISTS agent_tools (agent_id INTEGER REFERENCES agents(id) ON DELETE CASCADE, tool_id INTEGER, config TEXT DEFAULT '{}', PRIMARY KEY(agent_id,tool_id));
CREATE TABLE IF NOT EXISTS agent_runs (id TEXT PRIMARY KEY, agent_id INTEGER REFERENCES agents(id), prompt TEXT NOT NULL, status TEXT NOT NULL, progress INTEGER DEFAULT 0, result TEXT, tokens INTEGER DEFAULT 0, cost REAL DEFAULT 0, latency_ms INTEGER DEFAULT 0, started_at TEXT, completed_at TEXT);
CREATE INDEX IF NOT EXISTS idx_runs_status_started ON agent_runs(status,started_at DESC);
CREATE TABLE IF NOT EXISTS agent_events (id TEXT PRIMARY KEY, run_id TEXT REFERENCES agent_runs(id) ON DELETE CASCADE, sequence INTEGER NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL, detail TEXT, progress INTEGER, status TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(run_id,sequence));
CREATE INDEX IF NOT EXISTS idx_events_run_seq ON agent_events(run_id,sequence);
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY, title TEXT NOT NULL, status TEXT, assigned_agent_id INTEGER REFERENCES agents(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workflows (id INTEGER PRIMARY KEY, name TEXT NOT NULL, definition TEXT NOT NULL DEFAULT '{}', version INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workflow_nodes (id INTEGER PRIMARY KEY, workflow_id INTEGER REFERENCES workflows(id) ON DELETE CASCADE, type TEXT NOT NULL, config TEXT, x REAL, y REAL);
CREATE TABLE IF NOT EXISTS workflow_edges (id INTEGER PRIMARY KEY, workflow_id INTEGER REFERENCES workflows(id) ON DELETE CASCADE, source_id INTEGER REFERENCES workflow_nodes(id), target_id INTEGER REFERENCES workflow_nodes(id));
CREATE TABLE IF NOT EXISTS memories (id INTEGER PRIMARY KEY AUTOINCREMENT, content TEXT NOT NULL, kind TEXT NOT NULL, importance REAL DEFAULT .5, embedding_ref TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS memory_entities (id INTEGER PRIMARY KEY, memory_id INTEGER REFERENCES memories(id) ON DELETE CASCADE, name TEXT, entity_type TEXT, relationships TEXT);
CREATE TABLE IF NOT EXISTS tools (id INTEGER PRIMARY KEY, name TEXT UNIQUE, risk_level TEXT, enabled INTEGER DEFAULT 1, config TEXT);
CREATE TABLE IF NOT EXISTS models (id INTEGER PRIMARY KEY, provider TEXT, name TEXT, input_cost REAL, output_cost REAL, enabled INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS model_calls (id INTEGER PRIMARY KEY, run_id TEXT REFERENCES agent_runs(id), model_id INTEGER REFERENCES models(id), input_tokens INTEGER, output_tokens INTEGER, latency_ms INTEGER, cost REAL, status TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS evaluations (id INTEGER PRIMARY KEY, name TEXT, dataset TEXT, metrics TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS evaluation_runs (id INTEGER PRIMARY KEY, evaluation_id INTEGER REFERENCES evaluations(id), agent_id INTEGER REFERENCES agents(id), results TEXT, status TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS incidents (id INTEGER PRIMARY KEY, severity TEXT, title TEXT, status TEXT, diagnosis TEXT, confidence REAL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS approvals (id INTEGER PRIMARY KEY, run_id TEXT REFERENCES agent_runs(id), action TEXT, reason TEXT, risk TEXT, status TEXT DEFAULT 'pending', decided_by INTEGER REFERENCES users(id), decided_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS integrations (id INTEGER PRIMARY KEY, provider TEXT UNIQUE, status TEXT, encrypted_secret_ref TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT, resource_type TEXT, resource_id TEXT, metadata TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE, status TEXT, latency_ms INTEGER, checked_at TEXT DEFAULT CURRENT_TIMESTAMP);